1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.AfterMapping;
5	import org.mapstruct.Mapper;
6	import org.mapstruct.Mapping;
7	import org.mapstruct.MappingTarget;
8	import org.mapstruct.Named;
9	import org.springframework.data.domain.Page;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
14	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
15	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
16	
17	import java.time.LocalDate;
18	import java.time.temporal.ChronoUnit;
19	import java.util.Collection;
20	import java.util.List;
21	import java.util.Map;
22	
23	/**
24	 * Maps Owner & OwnerDto using Mapstruct
25	 */
26	@Mapper(uses = PetMapper.class)
27	public interface OwnerMapper {
28	
29	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
30	    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
31	    @Mapping(target = "telephoneDisplay", source = "owner", qualifiedByName = "formatTelephoneDisplay")
32	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "formatMembershipNumber")
33	    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "formatCheckDigit")
34	    @Mapping(target = "membershipPoints", source = "owner", qualifiedByName = "formatMembershipPoints")
35	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "formatMembershipLevel")
36	    @Mapping(target = "locality", source = "owner", qualifiedByName = "formatLocality")
37	    @Mapping(target = "timezone", source = "owner", qualifiedByName = "formatTimezone")
38	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "formatContactPreference")
39	    @Mapping(target = "bulkSignupWarning", ignore = true)
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /**
43	     * Derives an owner's preferred contact channel for the read-only {@code contactPreference}
44	     * field: {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
45	     */
46	    @Named("formatContactPreference")
47	    default String formatContactPreference(Owner owner) {
48	        if (owner == null) {
49	            return null;
50	        }
51	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
52	        return hasEmail ? "EMAIL" : "PHONE";
53	    }
54	
55	    /**
56	     * Derives an owner's {@code locality} from its region-and-hash customer code: the region is the
57	     * segment of the {@code '<REGION>-<HASH8>'} code before the first {@code '-'}, so the locality
58	     * always agrees with the identity's region (which itself prefers the postcode over the city,
59	     * defaulting to {@code 'UNKNOWN'}). Returns {@code 'UNKNOWN'} when no customer code is present.
60	     */
61	    @Named("formatLocality")
62	    default String formatLocality(Owner owner) {
63	        if (owner == null) {
64	            return null;
65	        }
66	        String code = owner.getCustomerCode();
67	        if (code == null || code.isBlank()) {
68	            return "UNKNOWN";
69	        }
70	        int dash = code.indexOf('-');
71	        return dash < 0 ? code : code.substring(0, dash);
72	    }
73	
74	    /**
75	     * Fixed region-to-timezone table mapping each canonical region to its IANA timezone name.
76	     */
77	    Map<String, String> REGION_TIMEZONE = Map.of(
78	        "NSW", "Australia/Sydney",
79	        "VIC", "Australia/Melbourne",
80	        "QLD", "Australia/Brisbane");
81	
82	    /**
83	     * Derives an owner's {@code timezone} as the IANA timezone name for its locality/region, using
84	     * the fixed region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
85	     * QLD-&gt;Australia/Brisbane). The region is taken from {@link #formatLocality(Owner)}, so the
86	     * timezone always agrees with the reported locality. Returns {@code null} when the region is not
87	     * in the table (e.g. {@code 'UNKNOWN'}).
88	     */
89	    @Named("formatTimezone")
90	    default String formatTimezone(Owner owner) {
91	        if (owner == null) {
92	            return null;
93	        }
94	        return REGION_TIMEZONE.get(formatLocality(owner));
95	    }
96	
97	    /**
98	     * Computes an owner's membership points for the read-only {@code membershipPoints} field. Points
99	     * start at 0 and accumulate: 2 when an email address is present, 1 when the owner had no
100	     * namesakes at creation (namesakeCount is 0), 2 for a household of 3 or more members, and 3 for
101	     * tenure of more than 365 days (measured from the registration date to the current date).
102	     */
103	    @Named("formatMembershipPoints")
104	    default Integer formatMembershipPoints(Owner owner) {
105	        if (owner == null) {
106	            return null;
107	        }
108	        int points = 0;
109	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
110	        if (hasEmail) {
111	            points += 2;
112	        }
113	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
114	        if (noNamesakes) {
115	            points += 1;
116	        }
117	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
118	            points += 2;
119	        }
120	        if (owner.getRegistrationDate() != null
121	            && ChronoUnit.DAYS.between(owner.getRegistrationDate(), LocalDate.now()) > 365) {
122	            points += 3;
123	        }
124	        return points;
125	    }
