127	    /**
128	     * Derives an owner's numeric membership level for the read-only {@code membershipLevel} field
129	     * from its membership points: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for
130	     * 6 or more points.
131	     */
132	    @Named("formatMembershipLevel")
133	    default Integer formatMembershipLevel(Owner owner) {
134	        Integer points = formatMembershipPoints(owner);
135	        if (points == null) {
136	            return null;
137	        }
138	        if (points <= 1) {
139	            return 1;
140	        }
141	        if (points <= 3) {
142	            return 2;
143	        }
144	        if (points <= 5) {
145	            return 3;
146	        }
147	        return 4;
148	    }
