150	    /**
151	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last
152	     * two digits of the registrationDate year (e.g. {@code 'NSW-1A2B3C4D-M26'}), for the read-only
153	     * {@code membershipNumber} field. Null when the customer code or registration date is absent.
154	     */
155	    @Named("formatMembershipNumber")
156	    default String formatMembershipNumber(Owner owner) {
157	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
158	            return null;
159	        }
160	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
161	    }
162	
163	    /**
164	     * Computes the Luhn check digit (0-9) over the digits contained in the owner's
165	     * {@code customerCode} for the read-only {@code checkDigit} field. Null when the
166	     * customer code is absent.
167	     */
168	    @Named("formatCheckDigit")
169	    default Integer formatCheckDigit(Owner owner) {
170	        if (owner == null || owner.getCustomerCode() == null) {
171	            return null;
172	        }
173	        String code = owner.getCustomerCode();
174	        int sum = 0;
175	        boolean dbl = true;
176	        for (int i = code.length() - 1; i >= 0; i--) {
177	            char c = code.charAt(i);
178	            if (c < '0' || c > '9') {
179	                continue;
180	            }
181	            int d = c - '0';
182	            if (dbl) {
183	                d *= 2;
184	                if (d > 9) {
185	                    d -= 9;
186	                }
187	            }
188	            sum += d;
189	            dbl = !dbl;
190	        }
191	        return (10 - (sum % 10)) % 10;
192	    }
193	
194	    /**
195	     * Formats an owner's stored names as {@code 'LastName, FirstName'} for the read-only
196	     * {@code displayName} field.
197	     */
198	    @Named("formatDisplayName")
199	    default String formatDisplayName(Owner owner) {
200	        return owner == null ? null : owner.getLastName() + ", " + owner.getFirstName();
201	    }
202	
203	    /**
204	     * Formats an owner's initials as the upper-cased first letters of firstName and
205	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), for the
206	     * read-only {@code initials} field.
